package com.learn.hub.search;

import java.util.List;

import co.elastic.clients.elasticsearch.ElasticsearchClient;
import co.elastic.clients.elasticsearch._types.FieldValue;
import co.elastic.clients.elasticsearch._types.Refresh;
import co.elastic.clients.elasticsearch._types.SortOrder;
import co.elastic.clients.elasticsearch.core.SearchResponse;
import co.elastic.clients.elasticsearch.core.search.Hit;
import org.springframework.stereotype.Repository;

/** 写入 wait_for 保证写完可搜；翻页用 search_after，避免深分页堆内存。 */
@Repository
public class TopicSearchRepository {

    private final ElasticsearchClient client;

    public TopicSearchRepository(ElasticsearchClient client) {
        this.client = client;
    }

    public void save(TopicDoc doc) throws Exception {
        client.index(i -> i
                .index("topics")
                .id(doc.slug())
                .document(doc)
                .refresh(Refresh.WaitFor));
    }

    public List<String> page(int size, List<FieldValue> after) throws Exception {
        SearchResponse<TopicDoc> resp = client.search(s -> s
                        .index("topics")
                        .size(size)
                        .sort(so -> so.field(f -> f.field("updatedAt").order(SortOrder.Desc)))
                        .searchAfter(after),
                TopicDoc.class);
        return resp.hits().hits().stream().map(Hit::id).toList();
    }
}
